    except: continue
    t=d.get('type')
    ts=d.get('timestamp','')[11:19]
    if t=='assistant':
        msg=d.get('message',{})
        for c in msg.get('content') or []:
            if c.get('type')=='text' and c['text'].strip():
                print(f'### A {ts}: {c[\"text\"][:600]}'.replace(chr(10),' '))
