    elif t=='user':
        c=d.get('message',{}).get('content')
        if isinstance(c,list):
            for x in c:
                if x.get('type')=='tool_result' and x.get('tool_use_id') in results:
                    r=results[x.get('tool_use_id')]
                    if r.strip():
                        print(f'    = {r[:350]}'.replace(chr(10),' '))
