import re, json
src=open('/tmp/tally-live-form.html',encoding='utf-8',errors='replace').read()
m=re.search(r'<script id="__NEXT_DATA__" type="application/json">(.*?)</script>', src, re.S)
d=json.loads(m.group(1))
found=[]
def walk(o):
    if isinstance(o,dict):
        if 'blocks' in o and isinstance(o['blocks'],list) and o['blocks']: found.append(o['blocks'])
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(d)
blocks=found[0]
# compact map: type, uuid8, grp8 + payload keys for non-option blocks
for b in blocks[:60]:
    t=b['type']; u=b.get('uuid','?')[:8]; g=b.get('groupUuid','?')[:8]
    p=b.get('payload',{})
    extra=''
    if t not in ('MULTIPLE_CHOICE_OPTION','CHECKBOX','DROPDOWN_OPTION'):
        keys=[k for k in p.keys() if k!='safeHTMLSchema']
        extra=' payload:'+','.join(keys) if keys else ''
        txt=p.get('safeHTMLSchema')
        if txt: extra+=' text='+json.dumps(txt[0][0] if txt and txt[0] else '')[:40]
    else:
        extra=f" idx={p.get('index')} req={p.get('isRequired')} first={p.get('isFirst')} last={p.get('isLast')}"
    print(f'{t:26} {u} grp:{g}{extra}')
EOF

