import re, json
src=open('/tmp/tally-circle-public.html',encoding='utf-8',errors='replace').read()
m=re.search(r'<script id="__NEXT_DATA__" type="application/json">(.*?)</script>', src, re.S)
if not m:
    print('NEXT_DATA missing — checking title:', re.search(r'<title>([^<]*)</title>', src).group(1) if re.search(r'<title>([^<]*)</title>', src) else '?')
else:
    d=json.loads(m.group(1)); found=[]
    def walk(o):
        if isinstance(o,dict):
            if 'blocks' in o and isinstance(o['blocks'],list) and o['blocks']: found.append(o['blocks'])
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(d)
    for b in found[0]:
        t=b['type']; p=b.get('payload',{})
        txt=p.get('title') or p.get('text') or ''
        if not txt and 'safeHTMLSchema' in p:
            flat=re.sub(r'<[^>]+>','',json.dumps(p['safeHTMLSchema']))
            txt=flat.strip('"[]')[:60]
        extra=f" idx={p.get('index')} req={p.get('isRequired')}" if 'index' in p else ''
        print(f"{t:24} {txt[:70]}{extra}")
EOF

