@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Lora:ital,wght@0,400;0,600;1,400&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer components {
  .landing-container {
    @apply max-w-[1440px] mx-auto px-6 md:px-10 lg:px-12 w-full;
  }
  .landing-section {
    @apply py-16 md:py-24;
  }
  .landing-section-alt {
    @apply border-y;
    background-color: color-mix(in srgb, var(--surface-2) 30%, transparent);
    border-color: color-mix(in srgb, var(--border) 40%, transparent);
  }
  .hero-portrait-frame {
    @apply relative;
  }
  .text-landing-muted {
    color: var(--text-muted);
  }
  .pill {
    @apply inline-flex items-center rounded-full px-3 py-1 font-medium;
  }
  .pill-ink {
    @apply bg-primary text-primary-foreground;
  }
  .pill-outline {
    @apply border border-border text-muted-foreground bg-transparent;
  }
}

@layer utilities {
  @keyframes marquee {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }
  .animate-marquee {
    animation: marquee 28s linear infinite;
  }
  .page-stack {
    @apply flex flex-col gap-4 w-full;
  }
}

:root {
  /* Core — warm paper light theme */
  --background: #f5f2ed;
  --foreground: #1a1a1a;
  --card: #faf8f4;
  --card-foreground: #1a1a1a;
  --popover: #faf8f4;
  --popover-foreground: #1a1a1a;
  --primary: #0a6e56;
  --primary-foreground: #ffffff;
  --secondary: #eeeae3;
  --secondary-foreground: #4a4a4a;
  --muted: #d4cfc6;
  --muted-foreground: #787878;
  --accent: #0a6e56;
  --accent-foreground: #ffffff;
  --destructive: #c0392b;
  --destructive-foreground: #ffffff;
  --border: #d4cfc6;
  --input: #e4dfd7;
  --ring: #0a6e5640;

  /* Surfaces */
  --surface-1: #faf8f4;
  --surface-2: #eeeae3;
