  /* Text scale */
  --text-primary: #111111;
  --text-secondary: #4a4a4a;
  --text-muted: #787878;
  --text-accent: #0a6e56;

  /* Extended accent */
  --accent-warm: #c97c3a;
  --accent-warm-muted: #f0e6d6;
  --accent-cool: #2a7fbd;

  /* Status */
  --success: #0a6e56;
  --warning: #c97c3a;
  --error: #c0392b;
  --info: #2a7fbd;

  /* Glass */
  --glass-bg: rgba(250, 248, 244, 0.72);
  --glass-border: rgba(255, 255, 255, 0.60);
  --glass-shadow: rgba(10, 25, 47, 0.10);

  /* Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;
  --radius: 0.75rem;

  /* Typography */
  --font-sans: 'Inter', 'SF Pro Display', system-ui, sans-serif;
  --font-display: 'Space Grotesk', 'Inter', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  --font-serif: 'Lora', 'Georgia', serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --container-max: 1200px;
  --container-wide: 1400px;
  --container-narrow: 720px;

  /* Shadows — light */
  --shadow-sm: 0 1px 3px rgba(10, 25, 47, 0.06), 0 1px 2px rgba(10, 25, 47, 0.04);
  --shadow-md: 0 4px 12px rgba(10, 25, 47, 0.08), 0 2px 4px rgba(10, 25, 47, 0.06);
  --shadow-lg: 0 10px 30px rgba(10, 25, 47, 0.10), 0 4px 8px rgba(10, 25, 47, 0.06);
  --shadow-xl: 0 20px 60px rgba(10, 25, 47, 0.12), 0 8px 16px rgba(10, 25, 47, 0.08);
  --shadow-glow-primary: 0 0 20px rgba(10, 110, 86, 0.25);

  /* Gradients */
  --gradient-bg-light:
    radial-gradient(ellipse at 70% 10%, rgba(10, 110, 86, 0.04) 0%, transparent 55%),
    radial-gradient(ellipse at 30% 90%, rgba(201, 124, 58, 0.04) 0%, transparent 55%),
    #f5f2ed;

  /* Legacy aliases */
  --navy: #0a192f;
  --light-navy: #112240;
  --lightest-navy: #233554;
  --slate: #8892b0;
  --light-slate: #a8b2d8;
  --lightest-slate: #ccd6f6;
  --white: #e6f1ff;
  --green: #0a6e56;
  --green-tint: rgba(10, 110, 86, 0.1);
}

.dark {
  --background: #0a192f;
  --foreground: #ccd6f6;
  --card: #112240;
