  .social-icon:hover {
    color: var(--primary);
    transform: translateY(-3px);
  }

  .scroll-indicator {
    animation: scrollBounce 2s infinite;
  }
  @keyframes scrollBounce {
    0%, 20%, 50%, 80%, 100% { transform: translateY(0) translateX(-50%); }
    40% { transform: translateY(10px) translateX(-50%); }
    60% { transform: translateY(5px) translateX(-50%); }
  }

  .section-header {
    @apply flex items-center gap-4 mb-12;
  }
  .section-title {
    @apply text-2xl sm:text-3xl md:text-4xl font-display font-semibold tracking-tight text-foreground whitespace-nowrap;
  }
  .section-line {
    @apply h-px bg-border flex-1 max-w-xs;
  }

  .tag-pill {
    @apply inline-flex items-center px-3 py-1 rounded-full text-xs font-mono border;
    color: var(--primary);
    border-color: var(--border);
    background: var(--surface-2);
  }

  .status-dot {
    @apply inline-block w-2 h-2 rounded-full;
  }
  .status-active {
    @apply bg-mint;
    box-shadow: 0 0 6px rgba(100, 255, 218, 0.6);
  }
  .status-progress {
    @apply bg-gold;
  }
  .status-deployed {
    @apply bg-cobalt;
  }
  .status-concept {
    @apply bg-periwinkle;
  }

  .admin-input {
    @apply w-full px-3 py-2.5 rounded-lg border border-border text-foreground text-sm transition-colors duration-200;
    background: var(--surface-2);
  }
  .admin-input:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 2px var(--ring);
  }

  .page-enter {
    animation: fadeIn 0.6s ease-out both;
  }

  .interactive-min {
    min-width: 44px;
    min-height: 44px;
  }

  /* ─── Admin panel — liquid glass (design guide v3) ─── */
  .admin-shell {
    background: var(--gradient-bg-light);
    position: relative;
    isolation: isolate;
  }
  .dark .admin-shell {
    background: var(--gradient-bg-dark);
  }

  .admin-mesh {
    @apply absolute inset-0 pointer-events-none overflow-hidden;
    z-index: 0;
  }

  .admin-content-shell {
    @apply flex-1 flex flex-col min-w-0 w-full;
  }
  @media (min-width: 1024px) {
    .admin-content-shell {
      @apply my-3 mr-3 rounded-2xl border shadow-lg overflow-hidden;
      border-color: color-mix(in srgb, var(--border) 50%, transparent);
      background-color: color-mix(in srgb, var(--card) 20%, transparent);
    }
  }

  .admin-card {
    backdrop-filter: blur(12px) saturate(150%);
    -webkit-backdrop-filter: blur(12px) saturate(150%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 4px 24px var(--glass-shadow),
      inset 0 1px 0 rgba(255, 255, 255, 0.12);
    border-radius: var(--radius-lg);
    transition: border-color 0.3s cubic-bezier(0.4, 0, 0.2, 1),
      box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }
  .admin-card-interactive {
    @apply admin-card glass-shimmer;
  }
  .admin-card-interactive:hover {
    border-color: var(--primary);
    box-shadow:
      0 8px 40px var(--glass-shadow),
      0 0 0 1px var(--primary),
      inset 0 1px 0 rgba(255, 255, 255, 0.20);
    transform: translateY(-2px);
  }

  .admin-stat-card {
