  }

  .admin-table-wrap {
    @apply admin-card overflow-hidden p-0;
  }
  .admin-table-wrap:hover {
    transform: none;
  }
  .admin-table-wrap table {
    @apply w-full text-sm;
  }

  .admin-sidebar {
    @apply glass;
    border-radius: 0;
    border-top: none;
    border-bottom: none;
    border-left: none;
    border-right: 1px solid var(--glass-border);
    box-shadow: 4px 0 24px var(--glass-shadow);
    z-index: 10;
  }

  .admin-header-bar {
    @apply glass-nav;
    z-index: 10;
  }

  .admin-nav-link {
    @apply relative flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-mono transition-colors duration-200;
    color: var(--text-muted);
  }
  .admin-nav-link:hover {
    color: var(--primary);
    background: var(--green-tint);
  }
  .admin-nav-link.active {
    color: var(--primary);
  }

  .admin-login-card {
    @apply glass-elevated glass-shimmer p-8 md:p-10;
  }

  .admin-theme-toggle {
    @apply interactive-min p-2 rounded-lg border transition-colors duration-200;
    color: var(--text-muted);
    border-color: var(--glass-border);
    background: color-mix(in srgb, var(--glass-bg) 80%, transparent);
  }
  .admin-theme-toggle:hover {
    color: var(--primary);
    border-color: color-mix(in srgb, var(--primary) 40%, var(--glass-border));
    background: var(--green-tint);
  }

  .visme-form-shell {
    background: var(--card);
    border-radius: calc(var(--radius) + 2px);
  }
  .visme-form-embed {
    position: relative;
    border-radius: var(--radius);
    overflow: hidden;
    isolation: isolate;
  }
  .visme-form-embed::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    border-radius: inherit;
    box-shadow: inset 0 0 0 1px var(--border);
    z-index: 1;
  }
  .visme-form-embed iframe {
    display: block;
    width: 100% !important;
    border: 0 !important;
    border-radius: inherit;
    background: var(--card);
    pointer-events: auto;
  }
