function scrollTo(href: string, close?: () => void) {
  if (href.startsWith('#')) {
    const el = document.getElementById(href.slice(1))
    if (el) window.scrollTo({ top: el.offsetTop - 80, behavior: 'smooth' })
    close?.()
    return
  }
}

type DropdownProps = {
  label: string
  links: { name: string; href: string }[]
  onNavigate: (href: string) => void
}

function NavDropdown({ label, links, onNavigate }: DropdownProps) {
  const [open, setOpen] = useState(false)
  return (
    <div
      className="relative"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <button
        type="button"
        className="flex items-center gap-1 text-sm text-muted-foreground hover:text-primary transition-colors py-2"
        onClick={() => setOpen(!open)}
      >
        {label}
        <ChevronDown size={14} className={cn('transition-transform', open && 'rotate-180')} />
      </button>
      {open && (
        <div className="absolute top-full left-0 pt-1 min-w-[180px] z-50">
          <div className="rounded-xl border border-border bg-card/95 backdrop-blur-md shadow-lg p-2">
            {links.map((link) =>
              link.href.startsWith('/') ? (
                <Link
                  key={link.name}
