24	function parseJsonArray(raw: unknown): string[] {
25	  if (Array.isArray(raw)) return raw.map(String)
26	  if (typeof raw !== 'string') return []
27	  try {
28	    const value = JSON.parse(raw) as unknown
29	    return Array.isArray(value) ? value.map(String) : []
