import { socialData as defaultSocial, type SocialPlatform } from '@/data/social'
import { prisma } from '@/lib/db'

export type SocialData = typeof defaultSocial

function parseJsonArray(raw: unknown, fallback: unknown[]): unknown[] {
  if (Array.isArray(raw)) return raw
  if (typeof raw === 'string') {
    try {
      const value = JSON.parse(raw) as unknown
      return Array.isArray(value) ? value : fallback
    } catch {
      return fallback
    }
  }
  return fallback
}

function mergeSocial(override: Record<string, unknown>): SocialData {
  const result = structuredClone(defaultSocial) as SocialData
  for (const key of Object.keys(override)) {
    if (key in defaultSocial && typeof override[key] === 'object' && override[key] !== null) {
      const base = result[key as SocialPlatform] as Record<string, unknown>
      const patch = override[key] as Record<string, unknown>
      const merged = { ...base, ...patch }
      if (key === 'github') {
        merged.pinnedRepos = parseJsonArray(merged.pinnedRepos, [...defaultSocial.github.pinnedRepos])
      }
      if (key === 'twitter') {
        merged.pinnedTweets = parseJsonArray(merged.pinnedTweets, [...defaultSocial.twitter.pinnedTweets])
      }
      ;(result as Record<string, unknown>)[key] = merged
    }
  }
  return result
}

export async function getSocialData(): Promise<SocialData> {
  try {
    const row = await prisma.siteSettings.findUnique({ where: { key: 'social_data' } })
    if (!row?.value) return defaultSocial
    const parsed = JSON.parse(row.value) as Record<string, unknown>
    return mergeSocial(parsed)
  } catch {
    return defaultSocial
  }
}

export type { SocialPlatform }

