import { useCallback, useEffect, useState } from 'react'
import { CheckCircle, X } from 'lucide-react'
import VismeApplicationForm from '@/components/visme-application-form'
import { notifyInnerCircleViaEmail } from '@/lib/visme-notify'

function unlockPageScroll() {
  document.body.style.overflow = ''
  document.body.style.position = ''
  document.body.style.top = ''
  document.body.style.width = ''
  document.documentElement.style.overflow = ''
}

export default function ApplicationModal({
  open,
  onClose,
}: {
  open: boolean
  onClose: () => void
}) {
  const [mounted, setMounted] = useState(false)
  const [closing, setClosing] = useState(false)
  const [completed, setCompleted] = useState(false)
  const [embedKey, setEmbedKey] = useState(0)

  useEffect(() => {
    if (open) {
      setMounted(true)
      setClosing(false)
      setCompleted(false)
      setEmbedKey((k) => k + 1)
    }
  }, [open])

  // Always restore scroll when modal is closed or unmounted (Visme may also lock the body)
  useEffect(() => {
    if (!open && !mounted) {
      unlockPageScroll()
    }
    return () => unlockPageScroll()
  }, [open, mounted])

  const finishClose = useCallback(() => {
    unlockPageScroll()
    setClosing(true)
    window.setTimeout(() => {
      setMounted(false)
      setClosing(false)
      setCompleted(false)
      unlockPageScroll()
      onClose()
    }, 320)
  }, [onClose])

  const handleComplete = useCallback(async () => {
    if (completed) return
    setCompleted(true)
    try {
      await notifyInnerCircleViaEmail()
    } catch {
      // Visme still captured the submission; email is best-effort
    }
    finishClose()
  }, [completed, finishClose])

  useEffect(() => {
    if (!mounted) return
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') finishClose()
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [mounted, finishClose])

  if (!open && !mounted) return null

  return (
    <div
      className={`fixed inset-0 z-50 overflow-y-auto overscroll-contain transition-opacity duration-300 ${
        closing ? 'opacity-0' : 'opacity-100'
      }`}
      role="dialog"
      aria-modal="true"
      aria-label="Inner Circle application"
    >
      {/* Backdrop — click to close */}
      <button
        type="button"
        className="fixed inset-0 bg-[rgba(10,25,47,0.75)] backdrop-blur-sm cursor-default"
        aria-label="Close application form"
        onClick={finishClose}
      />

      {/* Centered panel — scrolls with the overlay if the form is tall */}
      <div className="relative flex min-h-full items-start sm:items-center justify-center p-4 sm:p-6 pointer-events-none">
        <div
          className={`pointer-events-auto glass-elevated w-full max-w-4xl max-h-[min(92vh,900px)] flex flex-col transition-all duration-300 ease-out my-4 sm:my-8 ${
            closing ? 'scale-[0.98] opacity-0 translate-y-2' : 'scale-100 opacity-100 translate-y-0'
          }`}
          onClick={(e) => e.stopPropagation()}
        >
          <div className="flex justify-between items-center px-5 py-4 border-b border-border shrink-0">
            <div>
              <h3 className="text-lg font-display font-bold text-foreground">Apply to the Inner Circle</h3>
              <p className="text-xs font-mono text-muted-foreground mt-0.5">
                Kennedy reviews every application personally
              </p>
            </div>
            <button
              type="button"
              onClick={finishClose}
              className="p-2 text-muted-foreground hover:text-primary transition-colors"
              aria-label="Close"
            >
              <X size={20} />
            </button>
          </div>

          {completed ? (
            <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
              <CheckCircle className="text-primary mb-4" size={48} />
              <p className="font-display font-semibold text-lg">Application received</p>
              <p className="text-sm text-muted-foreground font-mono mt-2">Closing…</p>
            </div>
          ) : (
            <div className="overflow-y-auto overscroll-contain flex-1 min-h-0 p-2 sm:p-4 visme-form-shell">
              <VismeApplicationForm
                embedKey={embedKey}
                minHeight="600px"
                onComplete={handleComplete}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

