import Script from 'next/script'
import { useEffect, useId } from 'react'

const VISME_COMPLETE = 'KM_VISME_COMPLETE'

export function isVismeCompleteMessage(data: unknown): boolean {
  return (
    typeof data === 'object' &&
    data !== null &&
    'type' in data &&
    (data as { type: string }).type === VISME_COMPLETE
  )
}

export default function VismeApplicationForm({
  fullPage = false,
  minHeight = '70vh',
  onComplete,
  embedKey,
}: {
  fullPage?: boolean
  minHeight?: string
  onComplete?: () => void
  /** Change when remounting (e.g. modal open) so Visme re-inits cleanly */
  embedKey?: string | number
}) {
  const mountId = useId()

  useEffect(() => {
    if (!onComplete) return

    const handleMessage = (event: MessageEvent) => {
      if (isVismeCompleteMessage(event.data)) {
        onComplete()
        return
      }

      // Best-effort: some iframe providers emit submit hints (Visme may not)
      const origin = event.origin || ''
      if (!origin.includes('visme')) return

      const payload = event.data
      const text = typeof payload === 'string' ? payload.toLowerCase() : JSON.stringify(payload ?? '').toLowerCase()
      if (text.includes('submit') || text.includes('complete') || text.includes('success')) {
        onComplete()
      }
    }

    window.addEventListener('message', handleMessage)
    return () => window.removeEventListener('message', handleMessage)
  }, [onComplete])

  return (
    <div key={embedKey ?? mountId} className="visme-form-embed w-full">
      <div
        className="visme_d"
        data-title="Inner Circle Application"
        data-url="meq8xxzj-registration-form-template?fullPage=true"
        data-domain="forms"
        data-full-page={fullPage ? 'true' : 'false'}
        data-min-height={minHeight}
        data-form-id="184966"
      />
      <Script
        src="https://static-bundles.visme.co/forms/vismeforms-embed.js"
        strategy="lazyOnload"
      />
    </div>
  )
}

