import { auth } from '@/lib/auth'
import { canAccessPath, defaultPathForRole, type Role } from '@/lib/rbac'
import { NextResponse } from 'next/server'

export default auth((req) => {
  const { pathname } = req.nextUrl
  const isLogin = pathname === '/admin/login'
  const isAdmin = pathname.startsWith('/admin')

  if (isAdmin && !isLogin && !req.auth) {
    return NextResponse.redirect(new URL('/admin/login', req.url))
  }

  if (isLogin && req.auth) {
    const role = (req.auth.user?.role ?? 'admin') as Role
    return NextResponse.redirect(new URL(defaultPathForRole(role), req.url))
  }

  if (isAdmin && !isLogin && req.auth) {
    const role = req.auth.user?.role as Role | undefined
    if (!canAccessPath(role, pathname)) {
      const dest = defaultPathForRole(role ?? 'editor')
      const url = new URL(dest, req.url)
      url.searchParams.set('denied', '1')
      return NextResponse.redirect(url)
    }
  }

  return NextResponse.next()
})

export const config = {
  matcher: ['/admin/:path*'],
}

