import { auth } from '@/lib/auth'
import { NextResponse } from 'next/server'

export async function requireAdmin() {
  const session = await auth()
  if (!session) {
    return { session: null, error: NextResponse.json({ error: 'Unauthorized' }, { status: 401 }) }
  }
  return { session, error: null }
}

import NextAuth from 'next-auth'
import Credentials from 'next-auth/providers/credentials'
import type { Role } from '@/lib/rbac'

function resolveRole(password: string): Role | null {
  if (password === process.env.ADMIN_PASSWORD) return 'admin'
  if (process.env.EDITOR_PASSWORD && password === process.env.EDITOR_PASSWORD) return 'editor'
  return null
}

export const { handlers, signIn, signOut, auth } = NextAuth({
  providers: [
    Credentials({
      credentials: {
        password: { label: 'Password', type: 'password' },
      },
      authorize: async (credentials) => {
        const password = credentials?.password as string | undefined
        if (!password) return null
        const role = resolveRole(password)
        if (!role) return null
        return {
          id: role === 'admin' ? 'admin' : 'editor',
          name: role === 'admin' ? 'Kennedy Muritu' : 'Content Editor',
          role,
        }
      },
    }),
  ],
  callbacks: {
    jwt({ token, user }) {
      if (user?.role) token.role = user.role
      return token
    },
    session({ session, token }) {
      if (token.role) session.user.role = token.role as Role
      return session
    },
  },
  session: { strategy: 'jwt', maxAge: 7 * 24 * 60 * 60 },
  pages: { signIn: '/admin/login' },
  trustHost: true,
})

import { NextResponse } from 'next/server'

/** Legacy endpoint — applications now go through Visme Forms embed. */
export async function POST() {
  return NextResponse.json(
    { error: 'Applications are submitted via the Inner Circle form. This endpoint is deprecated.' },
    { status: 410 },
  )
}

