import 'server-only'

import { prisma } from '@/lib/db'

export type DayCount = { date: string; count: number; amount?: number }

async function safeQuery<T>(fn: () => Promise<T>, fallback: T): Promise<{ data: T; ok: boolean }> {
  try {
    return { data: await fn(), ok: true }
  } catch {
    return { data: fallback, ok: false }
  }
}

function last7Days(): Date[] {
  const days: Date[] = []
  for (let i = 6; i >= 0; i--) {
    const d = new Date()
    d.setHours(0, 0, 0, 0)
    d.setDate(d.getDate() - i)
    days.push(d)
  }
  return days
}

function dayKey(d: Date): string {
  return d.toISOString().slice(0, 10)
}

async function contactsByDay(): Promise<DayCount[]> {
  const since = new Date()
  since.setDate(since.getDate() - 6)
  since.setHours(0, 0, 0, 0)
  const rows = await prisma.contactThread.findMany({
    where: { createdAt: { gte: since } },
    select: { createdAt: true },
  })
  const map = new Map<string, number>()
  for (const d of last7Days()) map.set(dayKey(d), 0)
  for (const r of rows) {
    const k = dayKey(new Date(r.createdAt))
    if (map.has(k)) map.set(k, (map.get(k) ?? 0) + 1)
  }
  return last7Days().map((d) => ({ date: dayKey(d), count: map.get(dayKey(d)) ?? 0 }))
}

async function coffeeByDay(): Promise<DayCount[]> {
  const since = new Date()
  since.setDate(since.getDate() - 6)
  since.setHours(0, 0, 0, 0)
  const rows = await prisma.coffeeDonation.findMany({
    where: { createdAt: { gte: since }, status: 'completed' },
    select: { createdAt: true, amountKes: true },
  })
  const countMap = new Map<string, number>()
  const amountMap = new Map<string, number>()
  for (const d of last7Days()) {
    const k = dayKey(d)
    countMap.set(k, 0)
    amountMap.set(k, 0)
  }
  for (const r of rows) {
    const k = dayKey(new Date(r.createdAt))
    if (countMap.has(k)) {
      countMap.set(k, (countMap.get(k) ?? 0) + 1)
      amountMap.set(k, (amountMap.get(k) ?? 0) + r.amountKes)
    }
  }
  return last7Days().map((d) => {
    const k = dayKey(d)
    return { date: k, count: countMap.get(k) ?? 0, amount: amountMap.get(k) ?? 0 }
  })
}

export async function getDashboardData() {
  let degraded = false

  const wrap = async <T>(fn: () => Promise<T>, fallback: T) => {
    const r = await safeQuery(fn, fallback)
    if (!r.ok) degraded = true
    return r.data
  }

  const [
    projectCount,
    testimonialCount,
    publishedEssays,
    coffeeCount,
    coffeeTotalKes,
    contactCount,
    pendingCoffees,
    recentCoffees,
    recentContacts,
    recentEssays,
    coffeeTrend,
    contactTrend,
  ] = await Promise.all([
    wrap(() => prisma.project.count(), 0),
    wrap(() => prisma.testimonial.count(), 0),
    wrap(() => prisma.essay.count({ where: { status: 'published' } }), 0),
    wrap(() => prisma.coffeeDonation.count({ where: { status: 'completed' } }), 0),
    wrap(
      () =>
        prisma.coffeeDonation
          .aggregate({ where: { status: 'completed' }, _sum: { amountKes: true } })
          .then((r) => r._sum.amountKes ?? 0),
      0,
    ),
    wrap(() => prisma.contactThread.count(), 0),
    wrap(() => prisma.coffeeDonation.count({ where: { status: 'pending' } }), 0),
    wrap(
      () => prisma.coffeeDonation.findMany({ orderBy: { createdAt: 'desc' }, take: 5 }),
      [],
    ),
    wrap(
      () => prisma.contactThread.findMany({ orderBy: { createdAt: 'desc' }, take: 5 }),
      [],
    ),
    wrap(
      () => prisma.essay.findMany({ orderBy: { updatedAt: 'desc' }, take: 3 }),
      [],
    ),
    wrap(() => coffeeByDay(), []),
    wrap(() => contactsByDay(), []),
  ])

  return {
    degraded,
    kpis: {
      projects: projectCount,
      coffeeTotalKes,
      conversations: contactCount,
      publishedEssays,
      testimonials: testimonialCount,
      coffeesReceived: coffeeCount,
      pendingCoffees,
    },
    recentCoffees,
    recentContacts,
    recentEssays,
    coffeeByDay: coffeeTrend,
    contactsByDay: contactTrend,
  }
}

export type DashboardData = Awaited<ReturnType<typeof getDashboardData>>

