@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --font-serif: "Newsreader", Georgia, Cambria, "Times New Roman", serif;
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

html {
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  background-color: theme("colors.paper.DEFAULT");
  color: theme("colors.ink.DEFAULT");
  font-family: var(--font-serif);
}

/* Reading-first typography */
.prose-reader {
  font-size: 1.25rem;
  line-height: 1.9;
  letter-spacing: 0.005em;
}

.prose-reader p {
  margin-bottom: 1.6em;
}

.prose-reader h2 {
  font-size: 1.7rem;
  line-height: 1.3;
  margin-top: 2.6em;
  margin-bottom: 0.8em;
  letter-spacing: -0.01em;
}

.prose-reader h3 {
  font-size: 1.3rem;
  margin-top: 2em;
  margin-bottom: 0.6em;
}

/* Restrained accent for links */
.link-quiet {
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid theme("colors.accent.DEFAULT");
  padding-bottom: 1px;
  transition: color 0.4s ease, border-color 0.4s ease;
}

.link-quiet:hover {
  color: theme("colors.accent.DEFAULT");
}

/* Whitespace is a feature */
.breathe {
  scroll-margin-top: 6rem;
}

::selection {
  background: theme("colors.accent.soft");
  color: theme("colors.paper.DEFAULT");
}

