@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Lora:ital,wght@0,400;0,600;1,400&family=Space+Grotesk:wght@300;400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer components {
  .landing-container {
    @apply max-w-[1440px] mx-auto px-6 md:px-10 lg:px-12 w-full;
  }
  .landing-section {
    @apply py-16 md:py-24;
  }
  .landing-section-alt {
    @apply border-y;
    background-color: color-mix(in srgb, var(--surface-2) 30%, transparent);
    border-color: color-mix(in srgb, var(--border) 40%, transparent);
  }
  .hero-portrait-frame {
    @apply relative;
  }
  .text-landing-muted {
    color: var(--text-muted);
  }
  .pill {
    @apply inline-flex items-center rounded-full px-3 py-1 font-medium;
  }
  .pill-ink {
    @apply bg-primary text-primary-foreground;
  }
  .pill-outline {
    @apply border border-border text-muted-foreground bg-transparent;
  }
}

@layer utilities {
  @keyframes marquee {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }
  .animate-marquee {
    animation: marquee 28s linear infinite;
  }
  .page-stack {
    @apply flex flex-col gap-4 w-full;
  }
}

