@layer components {
  /* ─── Liquid glass system ─── */
  .glass {
    backdrop-filter: blur(16px) saturate(180%);
    -webkit-backdrop-filter: blur(16px) saturate(180%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 8px 32px var(--glass-shadow),
      inset 0 1px 0 rgba(255, 255, 255, 0.15),
      inset 0 -1px 0 rgba(0, 0, 0, 0.08);
    border-radius: var(--radius-xl);
  }

  .glass-elevated {
    backdrop-filter: blur(24px) saturate(200%);
    -webkit-backdrop-filter: blur(24px) saturate(200%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 20px 60px var(--glass-shadow),
      inset 0 2px 0 rgba(255, 255, 255, 0.20),
      inset 0 -1px 0 rgba(0, 0, 0, 0.12);
    border-radius: var(--radius-2xl);
  }

  .glass-nav {
    backdrop-filter: blur(20px) saturate(160%);
    -webkit-backdrop-filter: blur(20px) saturate(160%);
    background: var(--glass-bg);
    border-bottom: 1px solid var(--glass-border);
    box-shadow: 0 1px 0 var(--glass-border), 0 4px 20px var(--glass-shadow);
  }

  .glass-card {
    backdrop-filter: blur(12px) saturate(150%);
    -webkit-backdrop-filter: blur(12px) saturate(150%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 4px 24px var(--glass-shadow),
      inset 0 1px 0 rgba(255, 255, 255, 0.12);
    border-radius: var(--radius-lg);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .glass-card:hover {
    border-color: var(--primary);
    box-shadow:
      0 8px 40px var(--glass-shadow),
      0 0 0 1px var(--primary),
      inset 0 1px 0 rgba(255, 255, 255, 0.20);
    transform: translateY(-2px);
  }

  .glass-shimmer {
    position: relative;
    overflow: hidden;
  }
  .glass-shimmer::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -60%;
    width: 40%;
    height: 200%;
    background: linear-gradient(
      105deg,
      transparent 0%,
      rgba(255, 255, 255, 0.06) 40%,
      rgba(255, 255, 255, 0.14) 50%,
      rgba(255, 255, 255, 0.06) 60%,
      transparent 100%
    );
    transform: skewX(-20deg);
    transition: left 0.6s ease;
    pointer-events: none;
  }
  .glass-shimmer:hover::before {
    left: 120%;
  }

  .scroll-progress-bar {
    background: linear-gradient(90deg, var(--primary) 0%, #64ffda 50%, var(--accent-cool) 100%);
    height: 2px;
  }

  .hero-mesh {
    background:
      radial-gradient(at 27% 37%, hsla(215, 98%, 61%, 0.08) 0px, transparent 50%),
      radial-gradient(at 97% 21%, hsla(168, 100%, 80%, 0.07) 0px, transparent 50%),
      radial-gradient(at 52% 99%, hsla(215, 79%, 46%, 0.06) 0px, transparent 50%),
      radial-gradient(at 10% 29%, hsla(168, 100%, 50%, 0.05) 0px, transparent 50%);
