import Link from 'next/link'
import { auth } from '@/lib/auth'
import { NAV_ITEMS, can } from '@/lib/rbac'
import IntegrationStatus from '@/components/admin/integration-status'
import AdminKpiRow from '@/components/admin/dashboard/admin-kpi-row'
import AdminActivitySection from '@/components/admin/dashboard/admin-activity-section'
import AdminDashboardCharts from '@/components/admin/dashboard/admin-dashboard-charts'
