import { AdminPageHeader, adminBtnGhost } from '@/components/admin/admin-ui'
import { getDashboardData } from '@/lib/admin/dashboard'

export default async function AdminDashboardPage({
  searchParams,
}: {
  searchParams: Promise<{ denied?: string }>
}) {
  const { denied } = await searchParams
  const session = await auth()
  const role = session?.user?.role

  const data = await getDashboardData()

  const allowedHrefs = NAV_ITEMS.filter((item) => can(role, item.module, 'read')).map(
    (item) => item.href,
  )

  const kpiItems = [
    { label: 'Projects', value: data.kpis.projects, accent: true },
    {
      label: 'Coffee total',
      value: `KES ${data.kpis.coffeeTotalKes}`,
      subtext: `${data.kpis.coffeesReceived} received`,
      accent: true,
    },
    {
      label: 'Conversations',
      value: data.kpis.conversations,
      accent: true,
    },
    {
      label: 'Published essays',
      value: data.kpis.publishedEssays,
      subtext: `${data.kpis.testimonials} testimonials`,
      accent: true,
    },
  ]

  const showCoffees = can(role, 'coffees', 'read')
  const showCharts = showCoffees

  return (
    <div className="page-stack">
      {denied === '1' && (
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-4 py-2 text-xs font-mono text-amber-700 dark:text-amber-300">
          You don&apos;t have permission to access that page.
        </div>
      )}
      {data.degraded && (
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-4 py-2 text-xs font-mono text-amber-700 dark:text-amber-300">
          Some dashboard metrics could not be loaded. Showing partial data.
        </div>
      )}

      <AdminPageHeader
        number="00"
        label="dashboard"
        title="Overview"
        description="Portfolio control room"
        actions={
          <div className="flex flex-wrap gap-2">
            <Link href="/admin/projects/new" className={adminBtnGhost}>
              New project
            </Link>
          </div>
        }
      />

      <AdminKpiRow items={kpiItems} />

      {can(role, 'integrations', 'read') && <IntegrationStatus />}

      {showCoffees && (
        <div className="grid lg:grid-cols-2 gap-4">
          {showCoffees && (
            <AdminActivitySection
              title="Recent coffee tips"
              viewAllHref="/admin/coffees"
              columns={[
                { key: 'amount', header: 'Amount', render: (r) => `KES ${r.amountKes}` },
                { key: 'status', header: 'Status', render: (r) => r.status },
                {
                  key: 'date',
                  header: 'Date',
                  render: (r) => r.createdAt.toLocaleDateString(),
                },
              ]}
              rows={data.recentCoffees}
              emptyMessage="No tips yet"
            />
          )}
        </div>
      )}

      {showCharts && (
        <AdminDashboardCharts coffeeByDay={data.coffeeByDay} contactsByDay={data.contactsByDay} />
      )}

      <AdminQuickLinks allowedHrefs={allowedHrefs} />

      {can(role, 'community', 'read') && (
        <div className="rounded-xl border border-dashed border-border p-4 text-sm text-muted-foreground">
          <p className="font-medium text-foreground mb-1">Community applications</p>
          <p className="text-xs font-mono">
            New Inner Circle applications arrive via Visme Forms. Review submissions in your Visme
            dashboard or visit{' '}
            <Link href="/admin/community" className="text-primary hover:underline">
              Community admin
            </Link>
            .
          </p>
        </div>
      )}
    </div>
  )
}

