'use server'

import { z } from 'zod'
import { headers } from 'next/headers'
import { prisma } from '@/lib/db'
import {
  sendEmail,
  contactNotifyHtml,
  contactAutoReplyHtml,
} from '@/lib/email'
import { getAdminNotifyEmail } from '@/lib/env'
import { checkRateLimit } from '@/lib/rate-limit'
import { createHash } from 'crypto'

const contactSchema = z.object({
  name: z.string().min(2).max(100),
  email: z.string().email().max(200),
  subject: z.enum([
    'Project Enquiry',
    'Collaboration',
    'Speaking',
    'Community',
    'Enterprise Enquiry',
    'General',
  ]),
  message: z.string().min(20).max(5000),
  guestId: z.string().optional(),
})

export type ContactFormState = {
  ok: boolean
  error?: string
  guestId?: string
}

function guestIdFromEmail(email: string): string {
  return createHash('sha256').update(email.toLowerCase()).digest('hex').slice(0, 16)
}

export async function submitContactForm(
  _prev: ContactFormState,
  formData: FormData,
): Promise<ContactFormState> {
  const parsed = contactSchema.safeParse({
    name: formData.get('name'),
    email: formData.get('email'),
    subject: formData.get('subject'),
    message: formData.get('message'),
    guestId: formData.get('guestId') || undefined,
  })

  if (!parsed.success) {
    return { ok: false, error: parsed.error.errors[0]?.message ?? 'Invalid input' }
  }

  const hdrs = await headers()
  const ip = hdrs.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'
  const allowed = await checkRateLimit(`contact:${ip}`)
  if (!allowed) {
    return { ok: false, error: 'Too many messages. Please try again later.' }
  }

  const { name, email, subject, message } = parsed.data
  const guestId = parsed.data.guestId ?? guestIdFromEmail(email)
  const channelCid = `cid_${guestId}`

  await prisma.contactThread.upsert({
    where: { guestId },
    create: { guestId, guestName: name, guestEmail: email, channelId: channelCid },
    update: { guestName: name, guestEmail: email },
  })

  const adminEmail = getAdminNotifyEmail()
  const notify = await sendEmail(
    adminEmail,
    `[Portfolio] ${subject} — ${name}`,
    contactNotifyHtml(name, email, subject, message),
  )

  await sendEmail(email, 'Thanks for reaching out — Kennedy Muritu', contactAutoReplyHtml(name))

  if (!notify.ok) {
    return { ok: true, guestId, error: 'Message saved; email notification may be delayed.' }
  }

  return { ok: true, guestId }
}

const newsletterSchema = z.object({
  email: z.string().email().max(200),
})

export async function subscribeNewsletter(
  _prev: { ok: boolean; error?: string },
  formData: FormData,
): Promise<{ ok: boolean; error?: string }> {
  const parsed = newsletterSchema.safeParse({ email: formData.get('email') })
  if (!parsed.success) return { ok: false, error: 'Invalid email' }

  const hdrs = await headers()
  const ip = hdrs.get('x-forwarded-for')?.split(',')[0]?.trim() ?? 'unknown'
  const allowed = await checkRateLimit(`newsletter:${ip}`)
  if (!allowed) return { ok: false, error: 'Too many attempts. Try later.' }

  const adminEmail = getAdminNotifyEmail()
  const result = await sendEmail(
    adminEmail,
    'Newsletter subscription',
    `<p>New subscriber: ${parsed.data.email}</p>`,
  )

  if (!result.ok) return { ok: false, error: result.error }
  return { ok: true }
}

